#!/bin/bash
set -e

echo "=============================================="
echo "  VPS Manager 面板 v3.0 - 安装程序"
echo "  支持: Debian/Ubuntu (apt) + Alpine Linux (apk)"
echo "=============================================="
echo ""

# ---------- 可配置项（环境变量） ----------
# VP_MANAGER_ADMIN_PASS   管理员密码（不设则交互输入/自动生成）
# PHP_VERSION             PHP 版本: 8.2 / 8.3(默认) / 8.4 / 8.5
# WITH_MYSQL              是否安装 MySQL/MariaDB: 0(默认,SQLite 模式) / 1
# NGINX_OFFICIAL          Debian 使用 nginx.org 官方稳定版源: 0(默认,用发行版源) / 1

PHP_VERSION="${PHP_VERSION:-8.3}"
WITH_MYSQL="${WITH_MYSQL:-0}"
NGINX_OFFICIAL="${NGINX_OFFICIAL:-0}"

case "$PHP_VERSION" in
    8.2|8.3|8.4|8.5) ;;
    *) echo "❌ PHP_VERSION 仅支持 8.2 / 8.3 / 8.4 / 8.5"; exit 1 ;;
esac

IS_ALPINE=0
IS_RHEL=0
if [ -f /etc/alpine-release ]; then IS_ALPINE=1; fi
if [ -f /etc/redhat-release ]; then IS_RHEL=1; fi

# ---------- 管理员密码 ----------
if [ -n "$VP_MANAGER_ADMIN_PASS" ]; then
    ADMIN_PASS="$VP_MANAGER_ADMIN_PASS"
    echo "使用传入的管理员密码"
elif [ -t 0 ]; then
    read -sp "设置面板管理员密码（至少 6 位）: " ADMIN_PASS
    echo ""
    if [ -z "$ADMIN_PASS" ] || [ ${#ADMIN_PASS} -lt 6 ]; then
        echo "❌ 密码太短！"
        exit 1
    fi
    read -sp "确认密码: " ADMIN_CONFIRM
    echo ""
    if [ "$ADMIN_PASS" != "$ADMIN_CONFIRM" ]; then
        echo "❌ 两次输入不一致！"
        exit 1
    fi
else
    ADMIN_PASS=$(openssl rand -base64 12 2>/dev/null | tr -d '+/=' | head -c 12 || echo "Admin$(date +%s | md5sum | head -c 8)")
    echo "自动生成管理员密码: $ADMIN_PASS"
    echo "  请记好！登录后可在 设置 页修改"
fi

echo ""
echo ">>> 检测系统: $([ $IS_ALPINE -eq 1 ] && echo 'Alpine Linux' || ([ $IS_RHEL -eq 1 ] && echo 'CentOS/RHEL/Rocky/Alma' || echo 'Debian/Ubuntu'))"
echo ">>> PHP 版本: $PHP_VERSION | 安装 MySQL: $([ "$WITH_MYSQL" = "1" ] && echo 是 || echo 否（SQLite 模式）)"

# ---------- 依赖安装 ----------
if [ $IS_ALPINE -eq 1 ]; then
    echo ">>> apk 安装依赖..."
    apk update -q
    PV=$(echo "$PHP_VERSION" | tr -d '.')
    APK_PKGS="nginx curl unzip zip certbot certbot-nginx bash"
    APK_PKGS="$APK_PKGS php$PV php$PV-fpm php$PV-sqlite3 php$PV-pdo php$PV-pdo_sqlite php$PV-session php$PV-cli php$PV-curl php$PV-gd php$PV-mbstring php$PV-xml php$PV-zip php$PV-opcache php$PV-openssl php$PV-session"
    [ "$WITH_MYSQL" = "1" ] && APK_PKGS="$APK_PKGS mariadb mariadb-client php$PV-mysqli"
    apk add $APK_PKGS
elif [ $IS_RHEL -eq 1 ]; then
    echo ">>> dnf 安装依赖（CentOS/RHEL/Rocky/Alma）..."
    dnf install -y -q epel-release 2>/dev/null || dnf install -y -q https://dl.fedoraproject.org/pub/epel/epel-release-latest-9.noarch.rpm 2>/dev/null
    dnf install -y -q https://rpms.remirepo.net/enterprise/remi-release-9.rpm 2>/dev/null || true
    dnf module reset php -y -q 2>/dev/null || true
    dnf module enable php:remi-8.3 -y -q 2>/dev/null || true
    RHEL_PKGS="nginx curl unzip zip tar cronie"
    RHEL_PKGS="$RHEL_PKGS php php-fpm php-mysqlnd php-gd php-mbstring php-xml php-opcache"
    if [ "$WITH_MYSQL" = "1" ]; then RHEL_PKGS="$RHEL_PKGS mariadb-server mariadb"; fi
    dnf install -y -q $RHEL_PKGS || { echo "❌ dnf 安装依赖失败（certbot 可后装：dnf install certbot python3-certbot-nginx）"; }
    dnf install -y -q certbot python3-certbot-nginx 2>/dev/null || echo "ℹ️ certbot 未装（SSL 功能需 EPEL，可后补）"
else
    echo ">>> apt 安装依赖..."
    export DEBIAN_FRONTEND=noninteractive
    apt-get update -qq 2>/dev/null

    # nginx 官方稳定版源（可选）
    if [ "$NGINX_OFFICIAL" = "1" ] && ! grep -rq "nginx.org/packages" /etc/apt/sources.list.d/ 2>/dev/null; then
        echo ">>> 配置 nginx.org 官方稳定版源..."
        apt-get install -y -qq curl gnupg2 ca-certificates lsb-release 2>/dev/null
        curl -fsSL https://nginx.org/keys/nginx_signing.key | gpg --dearmor -o /usr/share/keyrings/nginx-archive-keyring.gpg 2>/dev/null
        CODENAME=$(lsb_release -sc 2>/dev/null || grep VERSION_CODENAME /etc/os-release | cut -d= -f2)
        echo "deb [signed-by=/usr/share/keyrings/nginx-archive-keyring.gpg] http://nginx.org/packages/debian $CODENAME nginx" > /etc/apt/sources.list.d/nginx.list
        echo "Package: *" > /etc/apt/preferences.d/nginx
        echo "Pin: origin nginx.org" >> /etc/apt/preferences.d/nginx
        echo "Pin-Priority: 900" >> /etc/apt/preferences.d/nginx
        apt-get update -qq 2>/dev/null
    fi

    # PHP PPA（Ubuntu 才需要；Debian 用 dhhh1/pkg 或 sury 源）
    if ! command -v php"$PHP_VERSION" &>/dev/null; then
        apt-get install -y -qq software-properties-common 2>/dev/null || true
        if [ -f /etc/debian_version ] && ! grep -qi ubuntu /etc/os-release; then
            # 纯 Debian：sury 源
            curl -sSLo /usr/share/keyrings/deb.sury.org-php.gpg https://packages.sury.org/php/apt.gpg 2>/dev/null
            echo "deb [signed-by=/usr/share/keyrings/deb.sury.org-php.gpg] https://packages.sury.org/php/ $(lsb_release -sc 2>/dev/null || echo bookworm) main" > /etc/apt/sources.list.d/php.list
        else
            # Ubuntu：ondrej PPA
            add-apt-repository -y ppa:ondrej/php 2>/dev/null || true
        fi
        apt-get update -qq 2>/dev/null
        if ! apt-cache show "php$PHP_VERSION-cli" >/dev/null 2>&1; then
            # 兜底：sury 源
            curl -sSLo /usr/share/keyrings/deb.sury.org-php.gpg https://packages.sury.org/php/apt.gpg 2>/dev/null || true
            echo "deb [signed-by=/usr/share/keyrings/deb.sury.org-php.gpg] https://packages.sury.org/php/ $(lsb_release -sc 2>/dev/null || echo bookworm) main" > /etc/apt/sources.list.d/php.list 2>/dev/null || true
            apt-get update -qq 2>/dev/null
        fi
    fi

    APT_PKGS="nginx curl unzip zip certbot python3-certbot-nginx cron"
    APT_PKGS="$APT_PKGS php$PHP_VERSION php$PHP_VERSION-sqlite3 php$PHP_VERSION-fpm php$PHP_VERSION-cli php$PHP_VERSION-curl php$PHP_VERSION-gd php$PHP_VERSION-mbstring php$PHP_VERSION-xml php$PHP_VERSION-zip php$PHP_VERSION-opcache"
    [ "$WITH_MYSQL" = "1" ] && APT_PKGS="$APT_PKGS mariadb-server mariadb-client php$PHP_VERSION-mysql phpmyadmin"
    DEBIAN_FRONTEND=noninteractive apt-get install -y -qq $APT_PKGS 2>/dev/null
fi

# ---------- 面板文件 ----------
echo ">>> 部署面板文件..."
if [ $IS_ALPINE -eq 1 ] || [ $IS_RHEL -eq 1 ]; then
    WEB_USER=nginx; WEB_GROUP=nginx
    [ -d /var/www ] || mkdir -p /var/www
else
    WEB_USER=www-data; WEB_GROUP=www-data
fi
mkdir -p /var/www/manager/backups
echo "" | base64 -d | gunzip > /var/www/manager/index.php
PHP_VER_SHA=$(sha256sum /var/www/manager/index.php | cut -d' ' -f1)
echo ">>> 面板 SHA-256: $PHP_VER_SHA"

echo "$ADMIN_PASS" > /var/www/manager/.passwd
chmod 600 /var/www/manager/.passwd

[ -d /usr/share/phpmyadmin ] && [ ! -L /var/www/manager/pma ] && ln -sf /usr/share/phpmyadmin /var/www/manager/pma
chown -R $WEB_USER:$WEB_GROUP /var/www/manager

# ---------- Nginx 配置 ----------
echo ">>> 配置 Nginx（端口 8080）..."
if [ $IS_ALPINE -eq 1 ]; then
    PV=$(echo "$PHP_VERSION" | tr -d '.')
    # Alpine php-fpm 默认监听 127.0.0.1:9000，改为 unix sock
    mkdir -p /run/php-fpm$PV
    sed -i "s|^listen = 127.0.0.1:9000|listen = /run/php-fpm$PV/php-fpm.sock|" /etc/php$PV/php-fpm.d/www.conf 2>/dev/null || \
        sed -i "s|^;listen = |listen = /run/php-fpm$PV/php-fpm.sock\n;listen = |" /etc/php$PV/php-fpm.d/www.conf 2>/dev/null || true
    sed -i "s|^;listen.owner = nobody|listen.owner = nginx|; s|^;listen.group = nobody|listen.group = nginx|" /etc/php$PV/php-fpm.d/www.conf 2>/dev/null || true
    sed -i "s|^user = nobody|user = nginx|; s|^group = nobody|group = nginx|" /etc/php$PV/php-fpm.d/www.conf 2>/dev/null || true
    FPM_SOCK="/run/php-fpm$PV/php-fpm.sock"
    NGX_DIR=/etc/nginx/http.d
    mkdir -p "$NGX_DIR"
    rm -f "$NGX_DIR/default.conf"
    NGX_CONF="$NGX_DIR/vps-manager.conf"
    PHP_INC="include fastcgi_params;
        fastcgi_index index.php;
        fastcgi_param SCRIPT_FILENAME \$document_root\$fastcgi_script_name;"
elif [ $IS_RHEL -eq 1 ]; then
    FPM_SOCK="/run/php-fpm/www.sock"
    NGX_DIR=/etc/nginx/conf.d
    NGX_CONF="$NGX_DIR/vps-manager.conf"
    PHP_INC="include fastcgi_params;
        fastcgi_index index.php;
        fastcgi_param SCRIPT_FILENAME \$document_root\$fastcgi_script_name;"
else
    FPM_SOCK="/var/run/php/php$PHP_VERSION-fpm.sock"
    NGX_DIR=/etc/nginx/sites-available
    NGX_CONF="$NGX_DIR/vps-manager"
    PHP_INC="include snippets/fastcgi-php.conf;"
fi
if [ $IS_RHEL -eq 1 ]; then
    sed -i "s|^;listen.acl_users = apache,nginx|listen.acl_users = nginx|" /etc/php-fpm.d/www.conf 2>/dev/null || true
    sed -i "s|^user = apache|user = nginx|; s|^group = apache|group = nginx|" /etc/php-fpm.d/www.conf 2>/dev/null || true
    # session 目录归 nginx 用户（RHEL 默认 root:apache，nginx worker 写不进→登录 session 丢失）
    mkdir -p /var/lib/php/session
    chown root:nginx /var/lib/php/session && chmod 770 /var/lib/php/session || true
fi
mkdir -p /var/www/manager
# ===== 面板生产形态：root php -S 常驻 + nginx 反向代理 =====
# 原因：面板「仅 root」模型（非 root POST 一律 403，T07b）。FPM worker 以 WEB_USER 运行，
# 若 nginx 直接 fastcgi 到 FPM，GET 正常但登录/建站等所有 POST 都会被 403 拦截。
# 因此：8080 由 nginx 纯 HTTP 反代到 127.0.0.1:9001 的 root PHP 内置服务器（OpenRC/systemd 常驻）。
cat > "$NGX_CONF" << NGX
server {
    listen 8080;
    server_name _;
    location / {
        proxy_pass http://127.0.0.1:9001;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        client_max_body_size 100M;
    }
}
NGX

# root 常驻面板服务
if [ $IS_ALPINE -eq 1 ]; then
    cat > /etc/init.d/vpsmgr-panel << PANEL
#!/sbin/openrc-run
name="vpsmgr-panel"
command="/usr/bin/php\$PV"
command_args="-S 127.0.0.1:9001 /var/www/manager/index.php"
command_background="yes"
pidfile="/run/vpsmgr-panel.pid"
directory="/var/www/manager"
depend() { need net; }
PANEL
    chmod +x /etc/init.d/vpsmgr-panel
else
    PHP_BIN=$(command -v php$PHP_VERSION || command -v php || echo /usr/bin/php)
    cat > /etc/systemd/system/vpsmgr-panel.service << PANEL
[Unit]
Description=VPS Manager Panel (root php -S)
After=network.target
[Service]
Type=simple
WorkingDirectory=/var/www/manager
ExecStart=$PHP_BIN -S 127.0.0.1:9001 index.php
Restart=always
[Install]
WantedBy=multi-user.target
PANEL
fi

if [ $IS_ALPINE -eq 1 ]; then
    rc-update add nginx default 2>/dev/null || true
    rc-update add php-fpm$(echo "$PHP_VERSION" | tr -d '.') default 2>/dev/null || true
    rc-update add vpsmgr-panel default 2>/dev/null || true
    [ "$WITH_MYSQL" = "1" ] && (rc-update add mariadb default 2>/dev/null; rc-service mariadb start 2>/dev/null || true)
    nginx -t && (rc-service nginx restart 2>/dev/null || nginx -s reload 2>/dev/null || true)
    rc-service php-fpm$(echo "$PHP_VERSION" | tr -d '.') start 2>/dev/null || true
    rc-service vpsmgr-panel start 2>/dev/null || true
else
    [ -e /etc/nginx/sites-enabled ] || { mkdir -p /etc/nginx/sites-enabled; grep -q "include /etc/nginx/sites-enabled" /etc/nginx/nginx.conf || sed -i '/http {/a\\    include /etc/nginx/sites-enabled/*;' /etc/nginx/nginx.conf; }
    rm -f /etc/nginx/sites-enabled/default
    [ $IS_RHEL -eq 1 ] || ln -sf "$NGX_CONF" /etc/nginx/sites-enabled/
    systemctl enable --now php-fpm 2>/dev/null || systemctl enable --now php$PHP_VERSION-fpm 2>/dev/null || true
    systemctl daemon-reload 2>/dev/null || true
    systemctl enable --now vpsmgr-panel 2>/dev/null || true
    [ "$WITH_MYSQL" = "1" ] && systemctl enable --now mariadb 2>/dev/null || true
    nginx -t && (systemctl enable --now nginx 2>/dev/null || rc-update add nginx default 2>/dev/null || (systemctl restart nginx 2>/dev/null || nginx -s reload 2>/dev/null) || true)
fi

# ===== 单用户收敛 CLI（T-02，DocumentRoot 外）+ 特权 helper（方案 A）=====
# T-18：备份移出 DocumentRoot
mkdir -p /var/lib/vps-manager/backups/migration && chmod 0700 /var/lib/vps-manager && chown $WEB_USER:$WEB_GROUP /var/lib/vps-manager /var/lib/vps-manager/backups /var/lib/vps-manager/backups/migration 2>/dev/null || true
# 旧备份迁移（DocumentRoot 内 → 新位置），无法迁移则保留原位并提示
if [ -d /var/www/manager/backups ]; then
  cp -an /var/www/manager/backups/. /var/lib/vps-manager/backups/ 2>/dev/null \
    && echo "ℹ 旧备份已复制到 /var/lib/vps-manager/backups（原目录保留，可手动删除）" \
    || echo "⚠ 旧备份迁移失败，原目录 /var/www/manager/backups 保留（nginx 已 deny）"
fi

mkdir -p /usr/local/share/vps-manager
echo "" | base64 -d > /usr/local/share/vps-manager/consolidate.php
chmod 0700 /usr/local/share/vps-manager/consolidate.php
mkdir -p /var/lib/vps-manager && chmod 0700 /var/lib/vps-manager
# 若检测到旧 .users 多账号遗留，提示执行收敛
[ -f /var/www/manager/.users ] && echo "ℹ 检测到遗留 .users 文件——如面板提示 503，请执行: php /usr/local/share/vps-manager/consolidate.php"

sleep 2

IP=$(curl -s4 ifconfig.me 2>/dev/null || hostname -I | awk '{print $1}')
echo ""
echo "=============================================="
echo "  ✅ 安装完成！"
echo "=============================================="
echo ""
echo "  面板地址:  http://$IP:8080"
echo "  用户名:    admin"
echo "  密码:      $ADMIN_PASS"
echo "  PHP:       $PHP_VERSION（可在面板 PHP 页加装 8.2-8.5 其他版本）"
[ "$WITH_MYSQL" = "1" ] && echo "  数据库:    MySQL/MariaDB 已安装" || echo "  数据库:    SQLite 模式（未装 MySQL，小内存友好）"
[ -d /usr/share/phpmyadmin ] && echo "  phpMyAdmin: http://$IP:8080/pma"
echo ""
echo "  ⚠️ 面板是 root 级工具：建议仅内网/SSH 隧道访问，或用防火墙限源（如 ufw allow from <你的IP> to any port 8080）"
echo "=============================================="
